"""Create the product-function inventory and its strict schema, without adopting effort."""
from pathlib import Path
import json,hashlib,sys
R=Path(__file__).resolve().parents[2];O=Path(__file__).resolve().parent;sys.path.insert(0,str(R/'tmp/model-deps'));import yaml
E=O/'evidence.json';data=json.loads(E.read_text(encoding='utf-8'))
proofs=list(data['evidence'].values());byproduct={p:sum(x['product']==p for x in proofs) for p in ['erpnext','odoo','tryton','axelor']}
functions=[]
links={'forms':['BC-080'],'process-studio':['BC-076','BC-077'],'analytics':['BC-088'],'process-mining':['BC-087']}
deps={'job-console':['jobs','permissions','audit-technical'],'retention':['jobs','permissions','audit-technical'],'backup':['jobs','permissions','settings'],'upgrades':['backup','settings'],'process-studio':['forms','permissions'],'process-mining':['analytics'],'analytics':['permissions'],'documents':['permissions'],'bulk-data':['permissions','job-console']}
for row in data['families']:
 refs=[o['evidence_ref'] for o in row['evidence']]
 functions.append(dict(id=row['id'],label=row['label'],purpose=row['purpose'].replace('_','-'),boundary=row['flow_boundary'],capability_refs=links.get(row['id'],[]),depends_on=deps.get(row['id'],[]),existing_funding_refs=row['existing_funding_refs'],evidence_refs=refs,qualification='coverage_to_review',note='Les références de financement sont des travaux existants à rapprocher, pas une preuve de couverture complète. Aucun complément en JH n’est adopté.',additional_jh=None))
purposes=[dict(id='business-runtime',label='Runtime et outils métier',definition='Services d’exécution des capacités et outils destinés aux utilisateurs métier : studios, tâches, formulaires, analyse et pilotage métier. Les fonctions IT déjà mêlées aux unités retenues restent à ventiler.'),dict(id='it-complement',label='Fonctions IT complémentaires',definition='Administration et robustesse du produit : habilitations, configuration, traitements techniques, sécurité, journaux, purges, sauvegarde et exploitabilité. Elles n’ajoutent aucune capacité à la cartographie métier reçue.')]
reading=dict(title='Distinguer les fonctions métier et les fonctions IT du produit',intro='La cartographie décrit le périmètre métier ; elle ne constitue pas l’inventaire complet d’un produit professionnel. Cette lecture complète le périmètre, sans créer de nouvelles capacités métier ni budget automatique.',adopted='Charge adoptée',business='Runtime et outils métier',it='Fonctions IT complémentaires',unallocated='Charge adoptée restant à ventiler',unknown='Non déterminé',no_estimate='Pas d’estimation adoptée',jh_unit='JH',allocation_note='Les unités retenues mêlent déjà des fonctions métier et IT. Aucun partage n’est déduit des rôles DevOps, QA ou sécurité. Une ventilation doit rattacher les travaux et répartir chaque JH une seule fois.',missing_note='Le complément nécessaire pour couvrir les fonctions encore insuffisamment dimensionnées reste inconnu. Il ne vaut pas zéro et ne s’ajoute pas automatiquement aux charges adoptées.',inventory_title='Fonctions professionnelles à instruire',function_label='Fonction du produit',purpose_label='Finalité',funding_label='Financement existant à vérifier',proof_label='Références OSS observées',scope_label='Travail et limite de couverture',progress_label='Avancement de l’inventaire',progress_note='Présence de code observée, distincte d’une couverture complète ou d’un chiffrage. Les 75 capacités hors Process Management n’ont pas été réauditées fonctionnellement lors de cet examen.',count_label='familles de fonctions',source_label='Voir le code de référence',review_label='Couverture à vérifier',unknown_additional='Complément à dimensionner',process_reservation='Les 340 JH de Process Management ne démontrent pas la couverture des studios, du portail de tâches, du Process Mining et des tableaux de bord précisés. Le contrôle COSMIC doit reprendre le même périmètre complet.')
doc=dict(version=1,id='core-product-functions',scope='construction_core',purposes=purposes,functions=functions,evidence=dict(path=E.relative_to(R).as_posix(),sha256=hashlib.sha256(E.read_bytes()).hexdigest()),allocations=[],reading=reading)
(R/'source/fonctions-produit-core.yaml').write_text(yaml.safe_dump(doc,allow_unicode=True,sort_keys=False,width=110),encoding='utf-8')
text=dict(type='string',minLength=1);texts=dict(type='array',items=text);identity=dict(type='string',pattern='^[a-z][a-z0-9-]*$')
def obj(props):return dict(type='object',additionalProperties=False,properties=props,required=list(props))
number=dict(type='number',minimum=0)
schema=obj(dict(version=dict(const=1),id=dict(const='core-product-functions'),scope=dict(const='construction_core'),purposes=dict(type='array',minItems=2,maxItems=2,items=obj(dict(id=dict(enum=['business-runtime','it-complement']),label=text,definition=text))),functions=dict(type='array',minItems=1,items=obj(dict(id=identity,label=text,purpose=dict(enum=['business-runtime','it-complement']),boundary=text,capability_refs=texts,depends_on=texts,existing_funding_refs=texts,evidence_refs=texts,qualification=dict(enum=['coverage_to_review','sufficiently_scoped']),note=text,additional_jh=dict(type=['number','null'],minimum=0)))),evidence=obj(dict(path=text,sha256=dict(type='string',pattern='^[a-f0-9]{64}$'))),allocations=dict(type='array',items=obj(dict(unit_id=identity,evidence_refs=dict(type='array',minItems=1,items=text),shares=dict(type='array',minItems=2,maxItems=2,items=obj(dict(purpose_id=dict(enum=['business-runtime','it-complement']),jh_by_role=dict(type='object',additionalProperties=number))))))),reading=obj({k:text for k in reading})))
schema['$schema']='https://json-schema.org/draft/2020-12/schema';(R/'source/schema-fonctions-produit-core.yaml').write_text(yaml.safe_dump(schema,allow_unicode=True,sort_keys=False,width=110),encoding='utf-8')
from collections import Counter
summary=dict(function_families=len(functions),purposes=dict(Counter(f['purpose'] for f in functions)),observed_code_files=len(proofs),observed_by_product=byproduct,already_in_measurements=sum(p['in_previous_measurements'] for p in proofs),not_in_measurements=sum(not p['in_previous_measurements'] for p in proofs),costs_not_adopted=True)
(O/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');print(json.dumps(summary))
